BEGIN READ ONLY; SET LOCAL statement_timeout='20s';
WITH valueset(v) AS (VALUES (NULL::text),(''),('plain'),('한글 식당'),('🔥🍽️'),('a|b'),(chr(101)||chr(769)),('https://www.youtube.com/watch?v=abcdefghijk')), comparisons AS (
SELECT public.generate_unique_id(a.v,b.v,c.v) before_trace,encode(sha256(convert_to(coalesce(a.v,'')||'|'||coalesce(b.v,'')||'|'||coalesce(c.v,''),'UTF8')),'hex') after_trace FROM valueset a CROSS JOIN valueset b CROSS JOIN valueset c), sigs(s) AS (VALUES ('public.canonicalize_youtube_link(text)'),('public.extract_youtube_video_id(text)'),('public.generate_unique_id(text,text,text)'),('public.is_user_admin(uuid)'),('public.normalize_restaurant_identity_name(text)'),('public.resolve_restaurant_identity_name(text,text,text,text)'))
SELECT jsonb_build_object('traceCases',(SELECT count(*) FROM comparisons),'traceMismatches',(SELECT count(*) FROM comparisons WHERE before_trace IS DISTINCT FROM after_trace),'privateOperator',jsonb_build_object('owner',(SELECT pg_get_userbyid(proowner) FROM pg_proc WHERE oid='pipeline_control.admin_record_assert_operator(uuid)'::regprocedure),'definer',(SELECT prosecdef FROM pg_proc WHERE oid='pipeline_control.admin_record_assert_operator(uuid)'::regprocedure),'anon',has_function_privilege('anon','pipeline_control.admin_record_assert_operator(uuid)','EXECUTE'),'authenticated',has_function_privilege('authenticated','pipeline_control.admin_record_assert_operator(uuid)','EXECUTE'),'service',has_function_privilege('service_role','pipeline_control.admin_record_assert_operator(uuid)','EXECUTE')),'legacyOwnerGrantMatrix',(SELECT jsonb_agg(jsonb_build_object('signature',s,'ownerExec',has_function_privilege('privacy_workflow_owner',s,'EXECUTE'),'serviceExec',has_function_privilege('service_role',s,'EXECUTE')) ORDER BY s) FROM sigs)); ROLLBACK;